//! 🧪️ Independent original currencies reach the actual derived semantic task before paid cancellation.
use super::*;
use semio_framework_value::ErasedSnapshotRetirement;
use crate::{ArtifactReplayPreparation, ArtifactReplayPreparationStep};
use crate::effect::{drive,drive_observed,with_work};
type Exit=semio_framework_value::RetirementPollExit;
struct CurrencyPreparation{bytes:ManuallyDrop<Option<Vec<u8>>>,closing:bool,copy:usize,capacity:usize,ledger:semio_framework_value::retained_clone::NativeAllocationIdentity,last_work:u64}
impl ArtifactReplayPreparation<u64,u64> for CurrencyPreparation{
 fn close_work_demand(&self,_:usize)->Result<u64,ValueError>{Ok(u64::from(self.bytes.is_some()))}
 fn last_turn_work(&self)->u64{self.last_work}
 fn advance_demands(&self,_:usize,_:u64)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:self.copy,capacity_bytes:self.capacity,depth:1,..Default::default()})}
 fn advance(&mut self,body:usize,g:ArtifactStoreOneItemGrant,c:&mut semio_framework_value_native_owned::native_decoding::NativeDecodeControl<'_>)->Result<ArtifactReplayPreparationStep,semio_framework_value::OriginalRetirementFailure>{self.last_work=0;assert_eq!(c.ledger_identity(),self.ledger);let d=self.advance_demands(4096,u64::MAX).unwrap();assert!(funded(g.retained_grant(),d));assert!(self.bytes.is_none());c.admit_turn_capacity(g.maximum_capacity_bytes)?;c.charge(self.capacity)?;self.last_work=1;let mut bytes=Vec::new();bytes.try_reserve_exact(self.capacity).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"original currency fixture allocation"))?;*self.bytes=Some(bytes);Ok(ArtifactReplayPreparationStep::Pending(RetainedCloneProgress{copied_items:1,copied_bytes:self.copy,retained_capacity_bytes:self.capacity,..Default::default()}))}
 fn take_prepared(&mut self)->Option<ArtifactReplayPrepared<u64,u64>>{None}
 fn cancel(&mut self){self.closing=true;}
 fn begin_close(&mut self){self.closing=true;}
 fn close_demands(&self,_:usize)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:size_of::<Option<Vec<u8>>>(),release_bytes:self.bytes.as_ref().map_or(0,Vec::capacity),depth:1,..Default::default()})}
 fn next_close_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(self.close_demands(4096)?.copy_bytes)}
 fn next_close_capacity_byte_demand(&self,_:usize)->Result<usize,ValueError>{Ok(0)}
 fn next_close_release_byte_demand(&self)->Result<usize,ValueError>{Ok(self.close_demands(4096)?.release_bytes)}
 fn next_close_depth_demand(&self)->Result<usize,ValueError>{Ok(1)}
 fn close_step(&mut self,effect:&mut semio_framework_value::RetainedAllocationEffect<'_>,c:&mut dyn semio_framework_value::OriginalRetirementControl)->semio_framework_value::OriginalRetirementPoll{self.last_work=0;let result=(||->Result<RetainedCloneStep,Exit>{let g=effect.grant();assert!(self.closing);assert_eq!(c.ledger_identity(),self.ledger);let d=self.close_demands(4096)?;if !funded(g,d){return Ok(RetainedCloneStep::Progress(Default::default()));}Exit::pay(effect,1)?;drop(self.bytes.take());Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})();Exit::settle(effect,result)}
 fn terminal_is_empty(&self)->bool{self.closing&&self.bytes.is_none()}
}
#[test]
fn original_derived_semantic_task_admits_copy_and_capacity_as_independent_currencies(){
 let law:serde_json::Value=serde_json::from_str(include_str!("./🧫️fixtures/🔣️.json")).unwrap();let f=&law["independentAxes"];let mut callback=|_:semio_framework_value_native_owned::native_decoding::NativeDecodeProgress|true;let mut recipient=semio_framework_value_native_owned::native_decoding::NativeDecodeRetirementRecipient::new();let mut receiving=semio_framework_value_native_owned::native_decoding::NativeDecodeControl::new(f["ownershipCeiling"].as_u64().unwrap()as usize,&mut callback);receiving.install_retirement_recipient(&mut recipient).unwrap();with_work(1024,&mut receiving,|receiving|{let ledger=receiving.ledger_identity();let context=ArtifactReplayPreparationContext{mode:ArtifactReplayPreparationMode::Prefix,operation_index:0,generation:7,base_revision:[9;32]};let cursor=CurrencyPreparation{bytes:ManuallyDrop::new(None),closing:false,copy:f["copyBytes"].as_u64().unwrap()as usize,capacity:f["capacityBytes"].as_u64().unwrap()as usize,ledger,last_work:0};
 let mut owner=ArtifactDerivedOperation::<u64,u64>{base:ManuallyDrop::new(None),producer:ManuallyDrop::new(None),registry:None,context,failed_read:ManuallyDrop::new(None),failed_input:ManuallyDrop::new(None),registry_close:ManuallyDrop::new(None),mode:ArtifactDerivedOperationMode::Provisional,policy:protocol::MergePolicy::default(),task:ManuallyDrop::new(Some(ArtifactReplayPreparationTask::new(context,Box::new(cursor)))),task_close:ManuallyDrop::new(None),prepared:ManuallyDrop::new(None),mutation:ManuallyDrop::new(None),retirement:ManuallyDrop::new(None),snapshots:ManuallyDrop::new(None),mutations:ManuallyDrop::new(None),factory_close:std::array::from_fn(|_|None),message:0,accepted:true,ready:false,finished:false,closing:false,last_work:0,progress:Default::default()};
 let d=owner.demands(7,[9;32],4096,1024).unwrap();assert!(d.copy_bytes+d.capacity_bytes>4096);let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:f["copyGrant"].as_u64().unwrap()as usize,maximum_capacity_bytes:f["capacityGrant"].as_u64().unwrap()as usize,maximum_release_bytes:65536,maximum_depth:64};
 for denied in [RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g}]{let(s,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(7,[9;32],4096,denied,receiving,&mut||false).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));}
 let(s,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(7,[9;32],4096,g,receiving,&mut||false).unwrap());assert_eq!(s.progress().copied_bytes,d.copy_bytes);assert_eq!(s.progress().retained_capacity_bytes,d.capacity_bytes);assert_eq!((h.requested_bytes,h.released_bytes),(d.capacity_bytes,0));assert_eq!(receiving.ledger_identity(),ledger);owner.cancel();assert_eq!(drive(RetainedCloneGrant{maximum_items:0,..g},|effect|owner.close_step(effect)).unwrap().progress(),Default::default());drive(g,|effect|owner.close_step(effect)).unwrap();assert!(owner.requires_original_control());let missing=drive(g,|effect|owner.close_step(effect)).unwrap_err();assert_eq!(missing.primary().unwrap().kind,ValueRefusalKind::UnsupportedOwner);let mut foreign_recipient=semio_framework_value_native_owned::native_decoding::NativeDecodeRetirementRecipient::new();let mut foreign_callback=|_:semio_framework_value_native_owned::native_decoding::NativeDecodeProgress|false;let mut foreign=semio_framework_value_native_owned::native_decoding::NativeDecodeControl::new(65536,&mut foreign_callback);foreign.install_retirement_recipient(&mut foreign_recipient).unwrap();let before=owner.progress();let foreign=foreign.with_retirement(g,|control|drive(g,|effect|owner.close_step_controlled(effect,control))).unwrap_err();assert_eq!(foreign.primary().unwrap().kind,ValueRefusalKind::OwnershipLimit);assert_eq!(serde_json::json!({"unfunded":"Progress","missingControl":format!("{:?}",missing.primary().unwrap().kind),"foreignControl":format!("{:?}",foreign.primary().unwrap().kind),"preservesProgress":owner.progress()==before}),law["retirementCustody"]);assert_eq!(owner.progress(),before);assert!(owner.task_close.is_some());while !owner.terminal_is_empty(){let d=owner.demands(7,[9;32],4096,1024).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(s,h)=receiving.with_retirement(g,|control|Ok::<_,semio_framework_value::OriginalRetirementFailure>(drive_observed(g,|effect|owner.close_step_controlled(effect,control)))).unwrap();let s=s.unwrap();assert_eq!((h.requested_bytes,h.released_bytes),(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert_eq!((semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner)).1.requested_bytes),0);Ok::<_,ValueError>(())}).unwrap();
}
